{
  "headline": "FDA's records trace our supply to a plant classified OAI 275 days before the posting",
  "headline_cites": ["D6"],
  "sentences": [
    {
      "text": "FDA first posted the rifampin injection shortage on 2021-02-17 and it remains Current as of 2026-10-21.",
      "cites": ["E19"]
    },
    {
      "text": "The shortage listing includes Fresenius Kabi USA, LLC, Mylan Institutional, a Viatris Company, and Sanofi-Aventis U.S. LLC.",
      "cites": ["E16", "E17", "E18"]
    },
    {
      "text": "Our Corvale sites hold the Mylan Institutional product (NDC 67457-445-60) manufactured at OneSource Specialty Pharma Limited in Bengaluru.",
      "cites": ["E2", "E4", "E5", "E15"]
    },
    {
      "text": "FDA inspected Fresenius Kabi USA, LLC (FEI 1450022) on 2020-05-18 and classified it OAI, with the classification letter issued 2024-05-22, 275 days before the shortage posting.",
      "cites": ["D6", "E11", "E14"]
    },
    {
      "text": "A second Fresenius Kabi inspection ended 2022-06-30 was also classified OAI, with the letter dated 2024-04-30, 498 days after the posting.",
      "cites": ["D7", "E12"]
    },
    {
      "text": "The highest-ranked mitigation is to transfer 17 vials of 600 mg/10 mL from Corvale Lakeside to Corvale East, which would raise Corvale East from 4.4 to 10 days on hand while leaving Corvale Lakeside with 14 days.",
      "cites": ["D11"]
    }
  ]
}
